@startuml

class Customer {
  + name : string
  + dateOfBirth : date
  + address : string
  + taxCode : string
}

class Broker {
  + brokerId : int
  + assignedCustomer : Customer
}

class Contract {
  + contractNumber : int
  + signingDate : date
  + insuredAmount : double
  + policyType : string
}

abstract class Policy {
  + text : string
}

class LifePolicy {}
class CarLiabilityPolicy {}
class TheftPolicy {}

class Claim {
  + claimId : int
  + claimDate : date
  + description : string
}

class ClaimCase {
  + caseId : int
  + claimDate : date
  + status : string
}

class Estimator {
  + estimatorId : int
  + areaOfExpertise : string
}

class CompensationDecision {
  + decisionId : int
  + compensationAmount : double
  + paymentDate : date
}

Customer "1" -- "0..*" Broker
Broker "1" -- "1" Customer
Customer "1" -- "0..*" Contract
Contract "1" -- "1" Policy
Policy "1" -- "0..*" Claim
Claim "1" -- "1" ClaimCase
Estimator "1" -- "0..*" ClaimCase
ClaimCase "1" -- "0..*" Estimator
ClaimCase "1" -- "1" CompensationDecision

@enduml

